/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isArrayArray = require( '@stdlib/assert/is-array-array' );
var isNumberArray = require( '@stdlib/assert/is-number-array' );
var isObjectArray = require( '@stdlib/assert/is-object-array' );
var isEmptyArray = require( '@stdlib/assert/is-empty-array' );
var format = require( '@stdlib/string/format' );
var everyBy2 = require( './../../every_by2.js' );


// FUNCTIONS //

/**
* Predicate function which tests whether two elements are equal.
*
* @private
* @param {Object} v1 - first value
* @param {Object} v2 - second value
* @returns {boolean} boolean indicating whether two elements are equal
*/
function predicate( v1, v2 ) {
	return ( v1.value === v2.value );
}

/**
* Validate the array.
*
* @private
* @param {Array} value - array of axises data
* @throws {TypeError}
*/
function validate( value ) {
	var i;

	if ( !isArrayArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of Array. Value: `%s`.', 'axis-data', value ) );
	}
	if ( value.length !== 4 ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of length 4. Value: `%s`.', 'axis-data', value ) );
	}
	for ( i = 0; i < 4; i++ ) {
		if ( isObjectArray( value[ i ] ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` cant be an array of object. Value: `%s`.', 'axis-data', value[ i ] ) );
		}
	}
}


// MAIN //

/**
* Sets the axis data.
*
* @private
* @param {Array} value - boolean indicating whether to automatically re-render on a `change` event
* @throws {TypeError} must be a boolean
*/
function set( value ) {
	var isChange = false;
	var i;

	validate( value );
	for ( i = 0; i < 4; i++ ) {
		// eslint-disable-next-line max-len
		if ( ( !this._axisDataObj[ i ].axis || !everyBy2( this._axisDataObj[ i ].data, value[ i ], predicate ) ) && value[ i ].length > 0 ) {
			this._axisDataObj[ i ].data = value[ i ];
			this._axisDataObj[ i ].axis = true;
			isChange = true;
		}
	}
	if ( isChange && !this._quite ) {
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
